const raw=JSON.parse(p); const memo=new Map();
function decRef(ref){
  if(typeof ref!=='number') return decVal(ref);
  if(ref<0) return undefined;
  if(memo.has(ref)) return memo.get(ref);
  const v=raw[ref];
  if(Array.isArray(v)){const out=[]; memo.set(ref,out); for(const x of v) out.push(decRef(x)); return out;}
  if(v&&typeof v==='object'){const out={}; memo.set(ref,out); for(const [k,x] of Object.entries(v)){const ki=Number(k.slice(1)); const key=decRef(ki); out[key]=decRef(x);} return out;}
  memo.set(ref,v); return v;
}
